mapper.select:
SELECT , el.collect_time AS last_collect_time, el.collect_time AS data_collect_time, el.forward_active_energy, el.reverse_active_energy, el.forward_reactive_energy, el.reverse_reactive_energy FROM meter_energy_history el INNER JOIN meter m ON m.id = el.meter_id LEFT JOIN distribution_box b ON b.id = m.box_id LEFT JOIN site s ON s.id = m.site_id
AND el.collect_time >= #{beginTime}
AND el.collect_time <= #{endTime}
ORDER BY el.collect_time DESC, m.id ASC

SELECT , COALESCE(ms.last_collect_time, qh.collect_time) AS last_collect_time, ms.last_publish_time, ms.status_code AS meter_status_code, ms.is_online, qh.collect_time AS data_collect_time, qh.current_thd_a, qh.current_thd_b, qh.current_thd_c, qh.voltage_thd_a, qh.voltage_thd_b, qh.voltage_thd_c, qh.voltage_unbalance, qh.current_unbalance FROM meter_power_quality_history qh INNER JOIN meter m ON m.id = qh.meter_id LEFT JOIN distribution_box b ON b.id = m.box_id LEFT JOIN site s ON s.id = m.site_id
AND qh.collect_time >= #{beginTime}
AND qh.collect_time <= #{endTime}
ORDER BY qh.collect_time DESC, m.id ASC
